// CLEAN CODE: Defensive programming with boundary validation.
// This code survives hacker-level boundary testing.

public class PlayerHealth : MonoBehaviour
{
    [SerializeField] private int maxHealth = 100;
    [SerializeField] private int currentHealth;
    [SerializeField] private bool isInvulnerable = false;
    [SerializeField] private bool isDead = false;

    public int CurrentHealth => currentHealth;
    public int MaxHealth => maxHealth;
    public bool IsDead => isDead;

    private void Awake()
    {
        currentHealth = maxHealth;
    }

    public void TakeDamage(int damage)
    {
        // Defensive: reject invalid states
        if (isDead) return;
        if (isInvulnerable) return;
        if (damage < 0)
        {
            Debug.LogWarning($"TakeDamage called with negative value: {damage}. Ignoring.");
            return;
        }

        // Apply damage with clamping
        currentHealth = Mathf.Max(0, currentHealth - damage);

        // Trigger events for UI, sound, particles
        OnHealthChanged?.Invoke(currentHealth, maxHealth);

        if (currentHealth <= 0)
        {
            Die();
        }
    }

    public void Heal(int amount)
    {
        if (isDead) return;
        if (amount < 0)
        {
            Debug.LogWarning($"Heal called with negative value: {amount}. Ignoring.");
            return;
        }

        // Clamp to max health — prevents overflow and UI glitches
        currentHealth = Mathf.Min(maxHealth, currentHealth + amount);
        OnHealthChanged?.Invoke(currentHealth, maxHealth);
    }

    public void SetInvulnerable(bool invulnerable)
    {
        isInvulnerable = invulnerable;
    }

    private void Die()
    {
        if (isDead) return;  // Prevent double-death
        isDead = true;

        OnDied?.Invoke();

        // Disable player controls, trigger death animation,
        // show game over UI after delay...
        StartCoroutine(DeathSequence());
    }

    private IEnumerator DeathSequence()
    {
        // Wait for death animation
        yield return new WaitForSeconds(2f);

        // Show game over screen
        GameOverManager.Instance?.ShowGameOver();
    }

    // Events for decoupled systems (UI, audio, achievements)
    public event System.Action<int, int> OnHealthChanged;
    public event System.Action OnDied;
}

// Example: A C# test case validator that checks if a test case object is well-formed
// This is useful for test management tools built in Unity

using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class TestCase
{
    public string testCaseId;
    public string title;
    public string feature;
    public List<string> preconditions;
    public List<string> steps;
    public string expectedResult;
    public string actualResult;
    public TestStatus status;
    public string environment;
    public string assignedTester;
    public DateTime createdDate;
    public DateTime? executedDate;

    public enum TestStatus
    {
        NotRun,
        InProgress,
        Passed,
        Failed,
        Blocked,
        Skipped
    }
}

public static class TestCaseValidator
{
    public static List<string> Validate(TestCase testCase)
    {
        var errors = new List<string>();

        if (string.IsNullOrWhiteSpace(testCase.testCaseId))
            errors.Add("Test Case ID is required");

        if (string.IsNullOrWhiteSpace(testCase.title))
            errors.Add("Title is required");

        if (testCase.preconditions == null || testCase.preconditions.Count == 0)
            errors.Add("At least one precondition is required");

        if (testCase.steps == null || testCase.steps.Count == 0)
            errors.Add("At least one step is required");

        if (string.IsNullOrWhiteSpace(testCase.expectedResult))
            errors.Add("Expected Result is required");

        // Check for vague expected results
        var vagueTerms = new[] { "works", "functions", "ok", "fine" };
        foreach (var term in vagueTerms)
        {
            if (testCase.expectedResult?.ToLower().Contains(term) == true)
                errors.Add($"Expected Result is too vague. Avoid using '{term}'. Be specific.");
        }

        return errors;
    }
}

// Usage example
public class TestCaseExample : MonoBehaviour
{
    void Start()
    {
        var testCase = new TestCase
        {
            testCaseId = "TC_COMBAT_001",
            title = "Player takes damage from enemy melee attack",
            feature = "Combat System",
            preconditions = new List<string>
            {
                "Player has 100 HP",
                "Enemy is within melee range (2 units)",
                "Game is in Play Mode"
            },
            steps = new List<string>
            {
                "Spawn player at origin (0, 0, 0)",
                "Spawn enemy at (2, 0, 0) facing player",
                "Trigger enemy attack animation",
                "Wait for attack hit frame (frame 12)",
                "Read player current HP"
            },
            expectedResult = "Player HP decreases by exactly 25. HP bar UI updates to show 75/100. Damage number '25' appears above player. Screen flashes red briefly.",
            environment = "Unity 2022.3.20f1, Windows 11, DX12, RTX 3060"
        };

        var errors = TestCaseValidator.Validate(testCase);
        if (errors.Count > 0)
        {
            Debug.LogError("Test Case Validation Failed:");
            foreach (var error in errors)
                Debug.LogError($"  - {error}");
        }
        else
        {
            Debug.Log("✅ Test Case TC_COMBAT_001 is valid and ready for execution");
        }
    }
}

// EDIT MODE TEST: Testing pure game logic without any scene or Play Mode
// File: Assets/Tests/EditMode/DamageCalculatorTests.cs

using NUnit.Framework;
using UnityEngine;

// Pure C# class — no MonoBehaviour, no Unity dependencies beyond Mathf
public class DamageCalculator
{
    public static int CalculateDamage(
        int baseDamage,
        float attackerStrength,
        float defenderDefense,
        bool isCriticalHit,
        float criticalMultiplier)
    {
        float damage = baseDamage * (attackerStrength / defenderDefense);

        if (isCriticalHit)
        {
            damage *= criticalMultiplier;
        }

        // Clamp to reasonable bounds
        damage = Mathf.Clamp(damage, 1, 9999);

        return Mathf.RoundToInt(damage);
    }

    public static bool IsCriticalHit(float luck, float threshold)
    {
        return luck >= threshold;
    }
}

// Edit Mode Test Class
public class DamageCalculatorTests
{
    [Test]
    public void CalculateDamage_NormalHit_ReturnsExpectedDamage()
    {
        // Arrange
        int baseDamage = 50;
        float attackerStrength = 10f;
        float defenderDefense = 5f;

        // Act
        int result = DamageCalculator.CalculateDamage(
            baseDamage, attackerStrength, defenderDefense, false, 2.0f);

        // Assert
        Assert.AreEqual(100, result, "Normal hit should deal 100 damage (50 * 10/5)");
    }

    [Test]
    public void CalculateDamage_CriticalHit_DoublesDamage()
    {
        // Arrange
        int baseDamage = 50;
        float attackerStrength = 10f;
        float defenderDefense = 5f;

        // Act
        int result = DamageCalculator.CalculateDamage(
            baseDamage, attackerStrength, defenderDefense, true, 2.0f);

        // Assert
        Assert.AreEqual(200, result, "Critical hit with 2x multiplier should deal 200 damage");
    }

    [Test]
    public void CalculateDamage_ZeroDefense_ClampedToMinimum()
    {
        // Arrange
        int baseDamage = 50;
        float attackerStrength = 10f;
        float defenderDefense = 0f;  // Division by zero risk!

        // Act
        int result = DamageCalculator.CalculateDamage(
            baseDamage, attackerStrength, defenderDefense, false, 2.0f);

        // Assert - The calculator should handle this gracefully
        Assert.GreaterOrEqual(result, 1, "Damage should never be less than 1");
    }

    [Test]
    public void IsCriticalHit_LuckAboveThreshold_ReturnsTrue()
    {
        // Arrange
        float luck = 75f;
        float threshold = 50f;

        // Act
        bool result = DamageCalculator.IsCriticalHit(luck, threshold);

        // Assert
        Assert.IsTrue(result, "Luck of 75 should exceed threshold of 50");
    }

    [Test]
    public void IsCriticalHit_LuckBelowThreshold_ReturnsFalse()
    {
        // Arrange
        float luck = 30f;
        float threshold = 50f;

        // Act
        bool result = DamageCalculator.IsCriticalHit(luck, threshold);

        // Assert
        Assert.IsFalse(result, "Luck of 30 should not exceed threshold of 50");
    }

    [Test]
    [TestCase(100, 10f, 5f, false, 2f, ExpectedResult = 200)]
    [TestCase(100, 10f, 10f, false, 2f, ExpectedResult = 100)]
    [TestCase(100, 10f, 20f, false, 2f, ExpectedResult = 50)]
    [TestCase(100, 10f, 5f, true, 2f, ExpectedResult = 400)]
    [TestCase(100, 10f, 5f, true, 3f, ExpectedResult = 600)]
    public int CalculateDamage_ParameterizedTests(
        int baseDamage, float strength, float defense, bool crit, float critMult)
    {
        return DamageCalculator.CalculateDamage(baseDamage, strength, defense, crit, critMult);
    }
}

// PLAY MODE TEST: Testing MonoBehaviour behavior in a real scene
// File: Assets/Tests/PlayMode/PlayerHealthPlayModeTests.cs

using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;

public class PlayerHealthPlayModeTests
{
    private GameObject playerObject;
    private PlayerHealth playerHealth;
    private GameObject enemyObject;
    private EnemyAttack enemyAttack;

    [UnitySetUp]
    public IEnumerator SetUp()
    {
        // Create a minimal test scene
        playerObject = new GameObject("TestPlayer");
        playerHealth = playerObject.AddComponent<PlayerHealth>();

        // Use reflection or a test-only setter to initialize private fields
        // In production, consider a TestablePlayerHealth subclass or interface
        playerHealth.GetType().GetField("maxHealth", 
            System.Reflection.BindingFlags.NonPublic | 
            System.Reflection.BindingFlags.Instance)?.SetValue(playerHealth, 100);
        playerHealth.GetType().GetField("currentHealth", 
            System.Reflection.BindingFlags.NonPublic | 
            System.Reflection.BindingFlags.Instance)?.SetValue(playerHealth, 100);

        // Create enemy
        enemyObject = new GameObject("TestEnemy");
        enemyAttack = enemyObject.AddComponent<EnemyAttack>();
        enemyAttack.damage = 25;

        // Wait one frame for Start() to execute
        yield return null;
    }

    [UnityTearDown]
    public IEnumerator TearDown()
    {
        // Clean up test objects
        Object.Destroy(playerObject);
        Object.Destroy(enemyObject);
        yield return null;
    }

    [UnityTest]
    public IEnumerator TakeDamage_ReducesHealthByCorrectAmount()
    {
        // Arrange
        int initialHealth = 100;
        int damage = 25;
        int expectedHealth = 75;

        // Act - Simulate enemy attack
        playerHealth.TakeDamage(damage);

        // Wait one frame for any coroutines or events to process
        yield return null;

        // Assert - Use reflection to read private field, or better, expose via property
        var healthField = playerHealth.GetType().GetField("currentHealth",
            System.Reflection.BindingFlags.NonPublic |
            System.Reflection.BindingFlags.Instance);
        int actualHealth = (int)healthField.GetValue(playerHealth);

        Assert.AreEqual(expectedHealth, actualHealth, 
            $"Health should be {expectedHealth} after taking {damage} damage");
    }

    [UnityTest]
    public IEnumerator TakeDamage_BelowZero_TriggersDeathEvent()
    {
        // Arrange
        bool deathEventFired = false;
        playerHealth.OnDied += () => deathEventFired = true;

        // Act - Deal massive damage
        playerHealth.TakeDamage(999);
        yield return null;

        // Assert
        Assert.IsTrue(deathEventFired, "Death event should fire when health reaches 0");

        // Verify isDead flag
        var isDeadField = playerHealth.GetType().GetField("isDead",
            System.Reflection.BindingFlags.NonPublic |
            System.Reflection.BindingFlags.Instance);
        bool isDead = (bool)isDeadField.GetValue(playerHealth);
        Assert.IsTrue(isDead, "Player should be marked as dead");
    }

    [UnityTest]
    public IEnumerator InvulnerablePlayer_TakesNoDamage()
    {
        // Arrange
        playerHealth.SetInvulnerable(true);
        int initialHealth = 100;

        // Act
        playerHealth.TakeDamage(50);
        yield return null;

        // Assert
        var healthField = playerHealth.GetType().GetField("currentHealth",
            System.Reflection.BindingFlags.NonPublic |
            System.Reflection.BindingFlags.Instance);
        int actualHealth = (int)healthField.GetValue(playerHealth);

        Assert.AreEqual(initialHealth, actualHealth,
            "Invulnerable player should take no damage");
    }

    [UnityTest]
    public IEnumerator Heal_ExceedsMaxHealth_ClampedToMax()
    {
        // Arrange - damage first, then overheal
        playerHealth.TakeDamage(50);  // Health now 50
        yield return null;

        // Act - heal more than the damage taken
        playerHealth.Heal(100);  // Would take health to 150, should clamp to 100
        yield return null;

        // Assert
        var healthField = playerHealth.GetType().GetField("currentHealth",
            System.Reflection.BindingFlags.NonPublic |
            System.Reflection.BindingFlags.Instance);
        int actualHealth = (int)healthField.GetValue(playerHealth);

        Assert.AreEqual(100, actualHealth,
            "Healing should not exceed max health");
    }
}
